package com.yeyamo_mobile.api.feed_service.application;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.feed_service.application.port.*;import com.yeyamo_mobile.api.feed_service.application.ranking.RankingStrategy;import com.yeyamo_mobile.api.feed_service.domain.model.FeedCandidate;
@Service public class FeedQueryService{private final FeedProjectionPort projections;private final FeedCachePort cache;private final RankingStrategy ranking;public FeedQueryService(FeedProjectionPort p,FeedCachePort c,RankingStrategy r){projections=p;cache=c;ranking=r;}
 @Transactional(readOnly=true)public FeedPage feed(String user,int page,int size){int p=Math.max(0,page),s=Math.max(1,Math.min(50,size));return cache.get(user,p,s).orElseGet(()->build(user,p,s));}
 private FeedPage build(String user,int page,int size){Instant now=Instant.now();Map<String,Double>affinity=projections.authorAffinities(user);int candidateLimit=Math.min(1000,Math.max(200,(page+1)*size*10));List<FeedItem>ranked=projections.candidates(candidateLimit).stream().map(c->item(c,ranking.score(c,affinity,now))).sorted(Comparator.comparingDouble(FeedItem::rankingScore).reversed().thenComparing(FeedItem::publishedAt,Comparator.reverseOrder())).toList();int from=Math.min(page*size,ranked.size()),to=Math.min(from+size,ranked.size());FeedPage result=new FeedPage(user,page,size,List.copyOf(ranked.subList(from,to)),now);cache.put(result);return result;}
 private FeedItem item(FeedCandidate c,double score){var p=c.post();var m=c.metric();return new FeedItem(p.postId(),p.authorId(),p.caption(),p.catalogAssetId(),p.mediaIds(),p.hashtags(),p.publishedAt(),m.likes(),m.comments(),m.shares(),Math.round(score*100d)/100d);}}
